import math
from ortools.sat.python import cp_model
import json

def main():
    model = cp_model.CpModel()

    days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri']
    schools = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']
    vehicles = [1, 2]

    kitchen_coords = (30.0, 40.0)

    school_coords = {
        'Alpha': (37.0, 52.0),
        'Beta': (49.0, 49.0),
        'Gamma': (52.0, 64.0),
        'Delta': (20.0, 26.0),
        'Epsilon': (40.0, 30.0)
    }

    meal_req = {
        'Alpha': 7.0,
        'Beta': 30.0,
        'Gamma': 16.0,
        'Delta': 9.0,
        'Epsilon': 21.0
    }

    vehicle_capacity = 160.0

    schedule_patterns = {
        'Alpha': [['Mon'], ['Tue'], ['Wed'], ['Thu'], ['Fri']],
        'Beta': [['Mon', 'Tue', 'Wed', 'Thu', 'Fri']],
        'Gamma': [['Mon', 'Wed'], ['Tue', 'Thu'], ['Wed', 'Fri']],
        'Delta': [['Mon'], ['Tue'], ['Wed'], ['Thu'], ['Fri']],
        'Epsilon': [['Mon', 'Wed'], ['Tue', 'Thu'], ['Wed', 'Fri']]
    }

    locations = ['C'] + schools

    def euclidean_distance(coord1, coord2):
        return math.sqrt((coord1[0] - coord2[0])**2 + (coord1[1] - coord2[1])**2)

    def get_coords(loc):
        if loc == 'C':
            return kitchen_coords
        else:
            return school_coords[loc]

    distance = {}
    for i in locations:
        for j in locations:
            if i == j:
                distance[(i, j)] = 0.0
            else:
                coord_i = get_coords(i)
                coord_j = get_coords(j)
                distance[(i, j)] = euclidean_distance(coord_i, coord_j)

    schedule_assignment = {}
    for s in schools:
        num_patterns = len(schedule_patterns[s])
        schedule_assignment[s] = [model.NewBoolVar(f"schedule_{s}_{k}") for k in range(num_patterns)]

    delivery_on_day = {}
    for s in schools:
        delivery_on_day[s] = {}
        for d in days:
            delivery_on_day[s][d] = model.NewBoolVar(f"delivery_{s}_{d}")

    assigned_to_vehicle = {}
    for s in schools:
        assigned_to_vehicle[s] = {}
        for d in days:
            assigned_to_vehicle[s][d] = {}
            for v in vehicles:
                assigned_to_vehicle[s][d][v] = model.NewBoolVar(f"assign_{s}_{d}_{v}")

    travel = {}
    for d in days:
        travel[d] = {}
        for v in vehicles:
            travel[d][v] = {}
            for i in locations:
                travel[d][v][i] = {}
                for j in locations:
                    if i != j:
                        travel[d][v][i][j] = model.NewBoolVar(f"travel_{d}_{v}_{i}_{j}")

    position = {}
    for d in days:
        position[d] = {}
        for v in vehicles:
            position[d][v] = {}
            for i in locations:
                position[d][v][i] = model.NewIntVar(0, len(schools), f"pos_{d}_{v}_{i}")

    for s in schools:
        model.AddExactlyOne(schedule_assignment[s])

    for s in schools:
        for d in days:
            patterns_with_d = []
            for k, pattern in enumerate(schedule_patterns[s]):
                if d in pattern:
                    patterns_with_d.append(schedule_assignment[s][k])

            if patterns_with_d:
                model.Add(delivery_on_day[s][d] == sum(patterns_with_d))
            else:
                model.Add(delivery_on_day[s][d] == 0)

    for s in schools:
        for d in days:
            vehicle_vars = [assigned_to_vehicle[s][d][v] for v in vehicles]
            model.Add(sum(vehicle_vars) == delivery_on_day[s][d])

    scaled_meal_req = {s: int(math.ceil(meal_req[s])) for s in schools}
    scaled_capacity = int(math.floor(vehicle_capacity))

    for d in days:
        for v in vehicles:
            capacity_expr = []
            for s in schools:
                capacity_expr.append(scaled_meal_req[s] * assigned_to_vehicle[s][d][v])
            model.Add(sum(capacity_expr) <= scaled_capacity)

    for d in days:
        for v in vehicles:
            start_expr = []
            for j in locations:
                if j != 'C':
                    start_expr.append(travel[d][v]['C'][j])
            vehicle_used = model.NewBoolVar(f'veh_used_{d}_{v}')
            model.Add(sum(assigned_to_vehicle[s][d][v] for s in schools) > 0).OnlyEnforceIf(vehicle_used)
            model.Add(sum(assigned_to_vehicle[s][d][v] for s in schools) == 0).OnlyEnforceIf(vehicle_used.Not())

            model.Add(sum(start_expr) == vehicle_used)

            end_expr = []
            for i in locations:
                if i != 'C':
                    end_expr.append(travel[d][v][i]['C'])
            model.Add(sum(end_expr) == vehicle_used)

    for d in days:
        for v in vehicles:
            for s in schools:
                incoming_expr = []
                for i in locations:
                    if i != s:
                        incoming_expr.append(travel[d][v][i][s])
                model.Add(sum(incoming_expr) == assigned_to_vehicle[s][d][v])

    for d in days:
        for v in vehicles:
            for s in schools:
                outgoing_expr = []
                for j in locations:
                    if j != s:
                        outgoing_expr.append(travel[d][v][s][j])
                model.Add(sum(outgoing_expr) == assigned_to_vehicle[s][d][v])

    num_schools = len(schools)
    for d in days:
        for v in vehicles:
            model.Add(position[d][v]['C'] == 0)
            for s in schools:
                model.Add(position[d][v][s] >= assigned_to_vehicle[s][d][v])
                model.Add(position[d][v][s] <= num_schools * assigned_to_vehicle[s][d][v])
                for t in schools:
                    if s != t:
                        mtz_expr = position[d][v][s] - position[d][v][t] + (num_schools + 1) * travel[d][v][s][t]
                        model.Add(mtz_expr <= num_schools)

    objective_terms = []
    big_multiplier = 1000000
    for d in days:
        for v in vehicles:
            for i in locations:
                for j in locations:
                    if i != j:
                        scaled_distance = int(distance[(i, j)] * big_multiplier)
                        objective_terms.append(scaled_distance * travel[d][v][i][j])

    model.Minimize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        schedules_output = []
        for s in schools:
            sched = [0, 0, 0, 0, 0]
            for d_idx, d in enumerate(days):
                if solver.Value(delivery_on_day[s][d]) == 1:
                    sched[d_idx] = 1
            schedules_output.append(sched)

        trajectories = []
        school_to_idx = {s: i+1 for i, s in enumerate(schools)}

        for d in days:
            daily_trajectories = []
            for v in vehicles:
                route = []
                current = 'C'
                visited = set()

                while True:
                    found_next = False
                    for j in locations:
                        if j != current and solver.Value(travel[d][v][current][j]) == 1:
                            if j == 'C' and current != 'C':
                                route.append(0)
                                found_next = True
                                break
                            elif j not in visited:
                                if current == 'C':
                                    route.append(0)
                                route.append(school_to_idx[j])
                                current = j
                                visited.add(j)
                                found_next = True
                                break
                    if not found_next or (route and route[-1] == 0):
                        break

                if len(route) > 1:
                    daily_trajectories.append(route)
            trajectories.append(daily_trajectories)

        total_distance = solver.ObjectiveValue() / float(big_multiplier)

        res = {
            "selected_temporal_engagement_schedules": schedules_output,
            "autonomous_vehicle_trajectories": trajectories,
            "total_spatial_displacement_expenditure": total_distance
        }
        print(json.dumps(res, indent=2))

    else:
        print("INFEASIBLE")

if __name__ == "__main__":
    main()
